        routes.append({"mode": "bm25", "query": "cache namespace proof regulated customer release feature evidence", "top_k": 35, "must_terms": ["cache", "namespace"], "should_terms": authority_terms})
    if not routes:
        routes.append({"mode": "dense", "query": query, "top_k": 50, "must_terms": [], "should_terms": []})

    for rewrite in rewrites:
        if rewrite and rewrite != query:
            rewrite_lower = rewrite.lower()
            rewrite_must = []
            for term in ["cache", "namespace", "release", "customer", "feature"]:
                if term in rewrite_lower:
                    rewrite_must.append(term)
            mode = "hybrid"
            if len(rewrite_must) >= 2 or "cache namespace" in rewrite_lower:
                mode = "bm25"
            routes.append({"mode": mode, "query": rewrite, "top_k": 30, "must_terms": rewrite_must, "should_terms": authority_terms + alias_terms})

    ctx.log("agentic_plan", {
        "query": query,
        "entities": entity_texts,
        "linked_entities": linked_entities,
        "rewrite_method": rewrite_result.get("method", ""),
        "rewrites": rewrites,
        "routes": routes,
        "goal": "Identify the customer, release evidence, and citable feature for cache namespace proof."
    })

    by_doc_id = {}
    order = []
    for route in routes:
        hits = ctx.search.search(
            route.get("query", query),
            mode=route.get("mode", "hybrid"),
            top_k=route.get("top_k", 30),
            bm25_weight=0.65 if route.get("mode") == "hybrid" and has_exactish_terms else 0.55,
            must_terms=route.get("must_terms", []),
            should_terms=route.get("should_terms", [])
        )
        for hit in hits:
            doc_id = hit.get("doc_id", "")
            if not doc_id:
                continue
            score = hit.get("score", 0)
            old = by_doc_id.get(doc_id)
            if old is None:
                by_doc_id[doc_id] = hit
                order.append(doc_id)
            else:
                old_score = old.get("score", 0)
                if score > old_score:
                    by_doc_id[doc_id] = hit

    candidates = []
    for doc_id in order:
        candidate = by_doc_id.get(doc_id)
        if candidate is not None:
            candidates.append(candidate)

    def candidate_score(candidate):
        text = ((candidate.get("title", "") or "") + " " + (candidate.get("text", "") or "")).lower()
        metadata = candidate.get("metadata", {}) or {}
        source = (metadata.get("source", "") or "").lower()
        doc_type = (metadata.get("doc_type", "") or "").lower()
        score = candidate.get("score", 0)
        bonus = 0
        for term in ["cache namespace", "cache", "namespace", "proof", "evidence", "regulated", "customer", "release", "feature"]:
            if term in text:
                bonus += 3
        for term in ["release", "changelog", "security", "compliance", "source of truth", "customer"]:
            if term in source or term in doc_type or term in text:
                bonus += 2
        if "deprecated" in text or "superseded" in text or "not available" in text:
            bonus -= 4
        return score + bonus

    candidates = sorted(candidates, key=candidate_score, reverse=True)
    candidates = candidates[:CANDIDATE_K]
    ctx.candidate_pool = len(candidates)

    ranked_hits = ctx.ranking.rerank(query, candidates, top_k=TOP_K)

    ctx.log("reflection", {
        "candidate_pool": len(candidates),
        "routes_used": len(routes),
        "reranked_top_k": TOP_K,
        "reasoning": "BM25 preserves exact cache namespace and release terms; hybrid/dense rewrites cover aliases, authority disambiguation, and the customer-release-feature join."
    })

    return {"hits": ranked_hits, "candidates": candidates}
